19	// ifaceDataMsg carries one read of this machine's interfaces.
20	type ifaceDataMsg struct {
21		interfaces []netiface.Interface
22		err        error
23	}
24	
25	// ifaceFetchTimeout bounds one read. The interfaces are a system call and the
26	// counters are another; neither waits on the network, so this is a backstop
27	// against a wedged platform call rather than a budget anything is expected to
28	// approach.
