55	type InterfacesModel struct {
56		width  int
57		height int
58	
59		table datatable.Model[netiface.Interface]
60	
61		loading bool
62		// lastOK dates the rows, and loadErr says the most recent read failed.
63		//
64		// A failed read keeps the rows on screen: they are not wrong, they are
65		// dated, and dropping them would leave the tab empty over a transient
66		// failure. What has to be said is their age — a footer *message* cannot
67		// carry it, since it expires after three seconds (Rule 128).
68		lastOK  time.Time
69		loadErr bool
70	
71		// footer is this tab's own message line. Each tab keeps one: a shared
72		// instance would let a message set here outlive the switch away from it.
73		footer components.FooterMessage
74	}
