76	func newInterfacesModel() *InterfacesModel {
77		return &InterfacesModel{
78			loading: true,
79			table: datatable.New(datatable.Config[netiface.Interface]{
80				Columns:    interfaceColumns(),
81				SortColumn: 0,
82			}),
83		}
84	}
