86	// interfaceColumns describes the interfaces table.
87	//
88	// The MAC is here because net.Interfaces() hands it over for nothing and the
89	// old tab threw it away — it is what a DHCP lease, a switch port and an asset
90	// inventory are all keyed on, so it is the field someone comes to this screen
91	// to copy.
92	func interfaceColumns() []datatable.Column[netiface.Interface] {
93		name := datatable.Column[netiface.Interface]{
94			Title: "Interface", Sizing: datatable.SizingContent, MinWidth: 16,
95			Cell:   func(i netiface.Interface) string { return i.Name },
96			Search: func(i netiface.Interface) string { return i.Name },
97			Less:   func(a, b netiface.Interface) bool { return a.Name < b.Name },
98		}
