100			Title: "State", Sizing: datatable.SizingFixed, MinWidth: 7,
101			Cell:  func(i netiface.Interface) string { return i.State },
102			Style: interfaceStateStyle,
103			Less:  func(a, b netiface.Interface) bool { return a.State < b.State },
104		}
