109					return "-"
110				}
111				return strconv.Itoa(i.MTU)
112			},
113			Style: func(i netiface.Interface) lipgloss.Style {
114				if !i.HasMTU() {
115					return theme.DimStyle
116				}
117				return lipgloss.Style{}
118			},
119			Less: func(a, b netiface.Interface) bool { return a.MTU < b.MTU },
120		}
121		mac := datatable.Column[netiface.Interface]{
122			Title: "MAC", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 17,
123			Cell:   macOrDash,
124			Search: func(i netiface.Interface) string { return i.MAC },
125			Style: func(i netiface.Interface) lipgloss.Style {
126				if i.MAC == "" {
127					return theme.DimStyle
128				}
129				return lipgloss.Style{}
130			},
131		}
132		rx := errorColumn("RX err", func(i netiface.Interface) *uint64 { return i.RxErrors })
133		tx := errorColumn("TX err", func(i netiface.Interface) *uint64 { return i.TxErrors })
134		// Both address columns follow their content and both carry a flex weight.
135		// The flex is what levels them against each other when there is a shortfall
136		// — a table reclaims from the widest content column first, so with the flex
137		// on IPv6 alone it used to absorb the whole shortfall and render at zero
138		// width from about 100 columns down, header included. IPv6 asks for more
139		// and grows faster because its notation is longer.
140		//
141		// Squeezed to nothing is no longer one of the outcomes (§3.45): MinWidth is
142		// a floor, and what gives way past it is a whole column, MTU / MAC / the
143		// two counters first because they are the ones marked Optional here.
144		v4 := addressColumn("IPv4", minIPv4Width, 1, netiface.Interface.IPv4List)
145		v6 := addressColumn("IPv6", minIPv6Width, 2, netiface.Interface.IPv6List)
146	
147		return []datatable.Column[netiface.Interface]{name, state, mtu, mac, rx, tx, v4, v6}
148	}
149	
150	// The address columns' minimum widths, from what the notation can hold:
151	// 255.255.255.255/32 is 18 characters, and a full IPv6 with its prefix length
152	// is 43. The IPv6 minimum is deliberately short of that — a column wide enough
153	// for the worst case would take half an 80-column terminal to serve the rare
154	// machine that has one, and the solver gives it the slack when there is any
155	// (Rule 116).
156	//
157	// The cliff §3.49 wrote down here is gone. It said that below about 88 columns
158	// the six exact-width columns took everything and both address columns were
159	// squeezed out — because MinWidth was an ask rather than a floor, and giving
160	// the solver one would have changed every table in the application. §3.45
161	// changed every table in the application. What gives way now is MTU, then MAC,
162	// then the two counters: they declare Optional, so they are removed whole and
163	// hand their width *and* their padding to the addresses.
164	const (
165		minIPv4Width = 18
166		minIPv6Width = 22
167	)
168	
169	// addressColumn builds one family's column.
170	//
171	// An interface with no address of this family renders a dim dash rather than an
172	// empty cell: a machine with IPv4 only has no IPv6 address, which is a fact
173	// about it, and a blank cell reads as a reading that failed. It is the same
174	// distinction the MAC column already makes.
175	//
176	// Neither column sorts. A list of addresses has no order anyone means, and
177	// sorting on the joined string would rank 10.x above 9.x — a lexical answer to
178	// a question nobody asked in text.
179	func addressColumn(title string, minWidth, flex int, list func(netiface.Interface) string) datatable.Column[netiface.Interface] {
180		return datatable.Column[netiface.Interface]{
181			Title: title, Sizing: datatable.SizingContent, MinWidth: minWidth, Flex: flex,
182			Cell: func(i netiface.Interface) string {
183				if s := list(i); s != "" {
184					return s
185				}
186				return "-"
187			},
188			Search: list,
189			Style: func(i netiface.Interface) lipgloss.Style {
190				if list(i) == "" {
191					return theme.DimStyle
192				}
193				return lipgloss.Style{}
194			},
195		}
196	}
197	
198	// macOrDash renders the hardware address, or says it has none.
199	//
200	// A loopback and a tunnel have no MAC, which is a fact about them rather than a
201	// missing reading — and an empty cell would look like the second.
202	func macOrDash(i netiface.Interface) string {
203		if i.MAC == "" {
204			return "-"
205		}
206		return i.MAC
207	}
208	
209	// errorColumn builds one of the two counter columns.
210	//
211	// The dash is D58 in a cell: the counters come from a source that fails on its
212	// own, and a zero written because nobody looked reads as an interface with no
213	// errors. So nil prints "-" and never "0", and the dash is dim because an
214	// absent reading is not a value worth spotting — a non-zero count is.
215	//
216	// This is the raw counter, since boot, per interface. The dashboard's
217	// Network box (§3.70) shows the same field aggregated across every
218	// interface and windowed since DevDesk started watching, not since boot —
219	// the two numbers are not meant to agree, and neither is a rollup of the
220	// other.
221	func errorColumn(title string, get func(netiface.Interface) *uint64) datatable.Column[netiface.Interface] {
222		return datatable.Column[netiface.Interface]{
223			Title: title, Sizing: datatable.SizingFixed, Optional: true, MinWidth: 8,
224			Cell: func(i netiface.Interface) string {
225				n := get(i)
226				if n == nil {
227					return "-"
228				}
229				return strconv.FormatUint(*n, 10)
230			},
231			Style: func(i netiface.Interface) lipgloss.Style {
232				n := get(i)
233				if n == nil || *n == 0 {
234					return theme.DimStyle
235				}
236				return theme.StatusWarningStyle
237			},
238			Less: func(a, b netiface.Interface) bool {
239				return errorCount(get(a)) < errorCount(get(b))
240			},
241		}
242	}
243	
244	// errorCount orders a counter for the sort. An unread counter sorts below zero
245	// so that descending — the direction anyone sorting this column wants — puts
246	// the interfaces that actually dropped frames on top, and never a row nobody
247	// managed to read.
248	func errorCount(n *uint64) int64 {
249		if n == nil {
250			return -1
251		}
252		return int64(*n)
253	}
254	
255	// interfaceStateStyle colours the state, which is the column this table is
256	// scanned down. Down is the one worth spotting; a loopback is neither news nor
257	// a problem.
258	func interfaceStateStyle(i netiface.Interface) lipgloss.Style {
259		switch i.State {
260		case netiface.StateDown, netiface.StateLoop:
261			return theme.DimStyle
262		default:
263			return theme.StatusOKStyle
264		}
265	}
266	
267	// initInterfaces returns the initial command: one read.
268	func (im *InterfacesModel) initInterfaces() tea.Cmd {
269		return fetchInterfacesCmd()
270	}
271	
272	// InEditMode reports whether a text field has the keyboard.
273	func (im *InterfacesModel) InEditMode() bool {
274		return im.table.FilterBar().InEditMode()
275	}
276	
277	func (im *InterfacesModel) resize(width, height int) {
278		im.width = width
279		im.height = height
280		// The full viewport width, borders included: Resize subtracts them itself, so
281		// the `-2` this used to carry subtracted them twice and the selected row
282		// stopped two cells short of the right border at every width. The
283		// `max(..., 20)` went with it: a floor above what the terminal has makes the
284		// table wider than the viewport, which is the overflow Rule 116 is about, and
285		// a narrow terminal is now handled by dropping columns (§3.45).
286		im.table.Resize(width, max(height, 3))
287	}
288	
289	func (im *InterfacesModel) update(msg tea.Msg) (*InterfacesModel, tea.Cmd) {
290		switch msg := msg.(type) {
291		case ifaceDataMsg:
292			return im.handleData(msg)
293		case tea.KeyPressMsg:
294			return im.handleKey(msg)
295		case tea.PasteMsg:
296			// Only the filter bar takes text; otherwise the paste is dropped (Rule 111).
297			if im.table.FilterBar().InEditMode() {
298				return im, im.table.Update(msg)
299			}
300			return im, nil
301		}
302		im.footer.Handle(msg)
303		return im, nil
304	}
305	
306	func (im *InterfacesModel) handleData(msg ifaceDataMsg) (*InterfacesModel, tea.Cmd) {
307		im.loading = false
308	
309		if msg.err != nil {
310			log.Printf("ERROR [netdiag/interfaces] list: %v", msg.err)
311			im.loadErr = true
312			return im, nil
313		}
314	
315		im.loadErr = false
316		im.lastOK = time.Now()
317		im.table.SetItems(msg.interfaces)
318		return im, nil
319	}
320	
321	func (im *InterfacesModel) handleKey(msg tea.KeyPressMsg) (*InterfacesModel, tea.Cmd) {
322		if im.table.FilterBar().InEditMode() {
323			return im, im.table.Update(msg)
324		}
325	
326		if msg.String() == "ctrl+r" {
327			im.loading = true
328			return im, fetchInterfacesCmd()
329		}
330	
331		return im, im.table.Update(msg)
332	}
333	
334	// statusLine is what this tab derives on every frame.
335	//
336	// Staleness outranks the load: a read that failed makes the rows on screen
337	// dated, and that has to keep being said while the next one runs.
338	func (im *InterfacesModel) statusLine() components.Status {
339		if im.loadErr {
340			return components.Status{Text: im.staleLabel(), Level: components.LevelError}
341		}
342		if im.loading {
343			return components.Status{Text: "Reading network interfaces...", Activity: true}
344		}
345		return components.Status{}
346	}
347	
348	// staleLabel dates the rows on screen, or says there are none to date.
349	func (im *InterfacesModel) staleLabel() string {
350		if im.lastOK.IsZero() {
351			return "The network interfaces could not be read"
352		}
353		return "The network interfaces could not be read — interfaces as of " + theme.TimeAgo(im.lastOK)
354	}
355	
356	// view renders the table. The body is never replaced by a spinner or a message
357	// (Rule 139): the table keeps its header and its columns while it refreshes or
358	// when it is empty, and the load and the row count are a footer status and a
359	// header field (summaryLine) respectively.
360	func (im *InterfacesModel) view() string {
361		return im.table.View()
362	}
363	
364	// summaryLine counts what is on screen, for the header.
365	func (im *InterfacesModel) summaryLine() string {
366		up := 0
367		for _, i := range im.table.Items() {
368			if i.State == netiface.StateUp {
369				up++
370			}
371		}
372		return fmt.Sprintf("%d up / %d total", up, len(im.table.Items()))
373	}
