	if a.showContextList {
		return a.handleContextListKeyMsg(msg)
	}

	if a.commandMode {
		return a.handleCommandMode(msg)
	}

	switch msg.String() {
	case "ctrl+c":
		return a, tea.Quit
	case "q":
		cmd := a.maybeQuitApplication(msg)
		return a, cmd
	case "?":
		return a.maybeOpenHelp(msg)
	case commandModeKey:
		// The authoritative way in: handled here, before any InEditMode() check,
		// so no text input can claim it. A bare ":" cannot play that role — it is
		// an ordinary character in a field holding https://trivy-server:4954.
		return a, a.enterCommandMode()
	case ":":
		cmd := a.maybeEnterInCommandMode(msg)
		return a, cmd
	// esc is deliberately absent: it belongs to the view. The router used to
	// answer it whenever the view was not editing, which made esc-to-go-back dead
	// code everywhere and forced views that wanted it to claim they were editing
	// — a predicate about focused fields, overloaded into one about key
	// ownership (§1.3 D15).
	//
	// Nothing is lost by handing it over: command mode is already closed by the
	// time this switch runs (handleCommandMode answers first), so the router had
	// nothing left to close.
	default:
		return a, a.forwardToActiveView(msg)
	}
}

// handlePasteMsg routes a bracketed paste. In v2 a paste is its own message,
// never a key press, so it cannot trigger an action (Rule 111): it is text for
// the field that has focus and for nothing else. Behind an overlay or a context
// switch it is dropped.
//
// Line ends are normalized here, the one point every paste goes through: a
// Windows paste ("a\r\nb") would otherwise leave two spaces in a single-line
// field, which turns each of \r and \n into a space.
func (a *App) handlePasteMsg(msg tea.PasteMsg) (tea.Model, tea.Cmd) {
	msg.Content = strings.ReplaceAll(msg.Content, "\r\n", "\n")
	switch {
	case a.switchingTo != "", a.showHelp, a.showContextList:
		return a, nil
	case a.commandMode:
		var cmd tea.Cmd
		before := a.commandInput.Value()
		a.commandInput, cmd = a.commandInput.Update(msg)
		if a.commandInput.Value() != before {
			a.refreshSuggestions()
		}
		return a, cmd
	case a.inEditMode():
		return a, a.forwardToActiveView(msg)
	}
	return a, nil
}

// forwardToActiveView hands a message to the current view and re-measures the
// layout when the view's footer changed shape in response (Rule 124) — opening
// a filter bar is the case that matters.
func (a *App) forwardToActiveView(msg tea.Msg) tea.Cmd {
	view, ok := a.views[a.currentView]
	if !ok {
		return nil
	}
	updatedView, cmd := view.Update(msg)
	a.setView(a.currentView, updatedView)
	if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
		a.resize(a.width, a.height)
	}
	return cmd
}

// enterCommandMode opens the command palette unconditionally. It asks for no
// re-layout: the palette is an overlay and changes no height.
//
// Focus is taken here rather than while rendering: a bubbles/textinput drops
// every key it receives while blurred, so granting focus from View() would make
// the command line depend on a render having happened first (Rule 110 — View()
// is read-only).
func (a *App) enterCommandMode() tea.Cmd {
	a.commandMode = true
	a.commandInput.Reset()
	a.commandInput.Focus()
	a.sugNotice = ""
	a.refreshSuggestions()
	return loadContextNamesCmd()
}

// inEditMode reports whether the active view has a focused field, which is what
// decides whether the router claims a key or passes it on.
func (a *App) inEditMode() bool {
	view, ok := a.views[a.currentView]
	if !ok {
		return false
	}
	formView, implements := view.(FormView)
	return implements && formView.InEditMode()
}

// maybeEnterInCommandMode answers a bare ":", which only opens the command line
// when nothing is being edited — inside a text input ":" is an ordinary
// character. Use altCommandModeKey to get in from anywhere.
func (a *App) maybeEnterInCommandMode(msg tea.Msg) tea.Cmd {
	if _, ok := a.views[a.currentView]; !ok {
		return nil
	}
	if !a.inEditMode() {
		return a.enterCommandMode()
	}

package components

import (
	"strings"

	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// BarFrame draws one line of content inside the rectangle that closes the
// viewport, and the rectangle's bottom edge under it.
//
// The viewport's own bottom border serves as the top of the rectangle, so the
// two lines here are the sides and the floor:
//
//	│  / cursor...                    Aa │
//	└────────────────────────────────────┘
//
// It is shared rather than copied because two things now occupy that one slot —
// the filter bar and the viewer's go-to-line prompt — and a second
// implementation of the frame would be free to disagree with the first about
// where the corners are. `inner` is already styled; it is padded to the width
// between the sides, so a caller measures nothing.
func BarFrame(width int, inner string) string {
	if width == 0 {
		width = 80
	}

	borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)

	// width-2 to leave room for │ on each side.
	padded := theme.PadWithBg(inner, width-2)
	content := borderStyle.Render("│") + padded + borderStyle.Render("│")
	bottom := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
	return content + "\n" + bottom
}

